import React from 'react';
import { Navigate } from 'react-router-dom';
import { useAuth } from "../AuthContext.jsx";

const ProtectedRoute = ({ children }) => {
  const { user, isLoading } = useAuth();

  if (isLoading) {
    console.log('ProtectedRoute: Waiting for auth to load'); // Debug log
    return <div className="min-h-screen bg-gradient-to-br from-black to-gray-900 flex items-center justify-center text-white">Loading...</div>; // Or a spinner component
  }

  if (!user) {
    console.log('ProtectedRoute: No user, redirecting to / with showSignIn state'); // Debug log
    return <Navigate to="/" state={{ showSignIn: true }} replace />;
  }

  console.log('ProtectedRoute: User authenticated, rendering children'); // Debug log
  return children;
};

export default ProtectedRoute;